-- RB-06 time off: leave types, public holidays, leave requests and the append-only balance ledger. Additive only:
-- no existing table changes. Generated by drizzle-kit, then hand-edited: statements reordered so referenced tables
-- come first, boolean defaults written as 0/1, and the append-only triggers, the four seeded leave types and the
-- `work_days` setting added (not expressible in schema.ts). Seeds use INSERT OR IGNORE, so a re-run changes nothing.
CREATE TABLE `leave_types` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`kind` text NOT NULL,
	`annual_half_days` integer DEFAULT 0 NOT NULL,
	`requires_reason` integer DEFAULT 0 NOT NULL,
	`active` integer DEFAULT 1 NOT NULL,
	`sort` integer DEFAULT 0 NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	CONSTRAINT "leave_types_kind_check" CHECK("leave_types"."kind" in ('balance', 'logged')),
	CONSTRAINT "leave_types_annual_check" CHECK("leave_types"."annual_half_days" between 0 and 730)
);
--> statement-breakpoint
CREATE UNIQUE INDEX `leave_types_name_uq` ON `leave_types` (lower("name"));
--> statement-breakpoint
CREATE TABLE `holidays` (
	`id` text PRIMARY KEY NOT NULL,
	`on_date` text NOT NULL,
	`name` text NOT NULL,
	`deducts_leave` integer DEFAULT 0 NOT NULL,
	`created_by` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`deleted_at` integer,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "holidays_deducts_check" CHECK("holidays"."deducts_leave" in (0, 1))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `holidays_date_uq` ON `holidays` (`on_date`) WHERE "holidays"."deleted_at" is null;
--> statement-breakpoint
CREATE TABLE `leave_requests` (
	`id` text PRIMARY KEY NOT NULL,
	`employee_id` text NOT NULL,
	`type_id` text NOT NULL,
	`start_on` text NOT NULL,
	`end_on` text NOT NULL,
	`half_day` text DEFAULT 'none' NOT NULL,
	`half_days` integer NOT NULL,
	`period` integer NOT NULL,
	`reason` text DEFAULT '' NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`decided_by` text,
	`decided_at` integer,
	`decision_note` text DEFAULT '' NOT NULL,
	`self_approved` integer DEFAULT 0 NOT NULL,
	`created_by` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`employee_id`) REFERENCES `employees`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`type_id`) REFERENCES `leave_types`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`decided_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "leave_requests_half_day_check" CHECK("leave_requests"."half_day" in ('none', 'am', 'pm')),
	CONSTRAINT "leave_requests_status_check" CHECK("leave_requests"."status" in ('pending', 'approved', 'rejected', 'canceled')),
	CONSTRAINT "leave_requests_half_days_check" CHECK("leave_requests"."half_days" >= 1),
	CONSTRAINT "leave_requests_self_approved_check" CHECK("leave_requests"."self_approved" in (0, 1))
);
